            "text": "الفصل الأول: الأعداد النسبية (Rational Numbers)\n\nمفهوم العدد النسبي:\nالعدد النسبي هو كل عدد يمكن كتابته على صورة كسر اعتيادي (a / b)، حيث a و b عددان صحيحان، والمقام b ≠ 0.\nمجموعة الأعداد النسبية يُرمز لها بالرمز (Q)، وتشمل:\n1. الأعداد الطبيعية والصحيحة (لأن أي عدد صحيح مقامه 1، مثل 5 = 5/1، -3 = -3/1).\n2. الكسور الاعتيادية والأعداد الكسرية (مثل 3/4، 2 1/3 = 7/3).\n3. الكسور العشرية المنتهية (مثل 0.25 = 25/100 = 1/4) والدورية (مثل 0.333... = 1/3).\n\nأولويات العمليات الحسابية على الأعداد النسبية:\n1. التخلص من الأعداد الكسرية بتحويلها إلى كسور اعتيادية: (العدد الصحيح × المقام + البسط) / المقام.\n2. البدء بالعمليات داخل الأقواس إن وُجدت.\n3. إجراء عمليات الضرب والقسمة من اليسار إلى اليمين.\n4. إجراء عمليات الجمع والطرح من اليسار إلى اليمين بعد توحيد المقامات."
