            "text": "الصورة العلمية للعدد:\nطريقة لكتابة الأعداد الكبيرة جداً أو الصغيرة جداً على صورة حاصل ضرب عدد قيمته المطلقة بين 1 و 10 في إحدى قوى العدد 10:\n   A × 10ⁿ  حيث 1 ≤ |A| < 10، و n عدد صحيح.\n\n1. تحويل العدد من الصورة الرقمية إلى الصورة العلمية:\n- إذا كان العدد كبيراً (|العدد| ≥ 10): نحرك الفاصلة لليسار ليصبح بين 1 و 10، ويكون الأس n موجباً ويساوي عدد المراتب المتحركة.\n  مثال: 72,000 = 7.2 × 10⁴\n- إذا كان العدد صغيراً جداً (0 < |العدد| < 1): نحرك الفاصلة لليمين ليصبح بين 1 و 10، ويكون الأس n سالباً ويساوي عدد المراتب المتحركة.\n  مثال: 0.00035 = 3.5 × 10⁻⁴\n\n2. تحويل العدد من الصورة العلمية إلى الصورة الرقمية:\n- إذا كان الأس موجباً: نحرك الفاصلة إلى اليمين بمقدار الأس n.\n  مثال: 4.2 × 10⁵ = 420,000\n- إذا كان الأس سالباً: نحرك الفاصلة إلى اليسار بمقدار الأس n.\n  مثال: 6.8 × 10⁻³ = 0.0068."
