            "text": "الخصائص الجبرية للقوى والأسس (لكل a, b ≠ 0):\n\n1. خاصية ضرب قوتين لهما الأساس نفسه (عند الضرب تجمع الأسس):\n   aᵐ × aⁿ = aᵐ⁺ⁿ\n   أمثلة:\n   2³ × 2⁴ = 2³⁺⁴ = 2⁷ = 128\n   5⁻³ × 5⁷ = 5⁻³⁺⁷ = 5⁴ = 625\n   7⁻² × 7⁻⁵ = 7⁻²⁺⁽⁻⁵⁾ = 7⁻⁷ = 1 / 7⁷\n\n2. خاصية قسمة قوتين لهما الأساس نفسه (عند القسمة تطرح الأسس):\n   aᵐ / aⁿ = aᵐ⁻ⁿ\n   أمثلة:\n   3⁶ / 3² = 3⁶⁻² = 3⁴ = 81\n   2⁻⁴ / 2³ = 2⁻⁴⁻³ = 2⁻⁷\n   5³ / 5⁻² = 5³⁻⁽⁻²⁾ = 5³⁺² = 5⁵\n\n3. خاصية رفع قوة إلى قوة أخرى (قوة القوة - عند الرفع تضرب الأسس):\n   (aᵐ)ⁿ = aᵐˣⁿ\n   أمثلة:\n   (3²)⁴ = 3²ˣ⁴ = 3⁸\n   (10⁻³)² = 10⁻⁶\n   (2⁻²)⁻³ = 2⁽⁻²⁾ˣ⁽⁻³⁾ = 2⁶ = 64\n\n4. توزيع الأس على الضرب والقسمة:\n   (a × b)ⁿ = aⁿ × bⁿ\n   (a / b)ⁿ = aⁿ / bⁿ (حيث b ≠ 0)."
