            "text": "1. جمع وطرح الأعداد بالصورة العلمية:\n- يجب توحيد قوى العدد 10 أولاً بجعل الأسس متطابقة عبر تحريك الفاصلة العشرية، ثم استخراج (10ⁿ) كعامل مشترك وجمع أو طرح الأجزاء العشرية.\nمثال:\n(4.1 × 10⁴) + (0.24 × 10⁵)\n= (4.1 × 10⁴) + (2.4 × 10⁴) = (4.1 + 2.4) × 10⁴ = 6.5 × 10⁴.\n\n2. ضرب وقسمة الأعداد بالصورة العلمية:\n- في الضرب: نضرب الأعداد العشرية معاً، ونجمع أسس قوى العدد 10:\n  (A × 10ᵐ) × (B × 10ⁿ) = (A × B) × 10ᵐ⁺ⁿ\n- في القسمة: نقسم الأعداد العشرية، ونطرح أسس قوى العدد 10:\n  (A × 10ᵐ) ÷ (B × 10ⁿ) = (A ÷ B) × 10ᵐ⁻ⁿ\n- وإذا لم يكن الناتج A بين 1 و 10 نعيد ضبط الفاصلة والأس."
