            "text": "الكسر العشري الدوري:\nهو عدد عشري لا تنتهي أرقامه وتتكرر فيه خانة أو مجموعة من الخانات بانتظام، ويُوضع خط أفقي فوق الخانة المتكررة.\nأمثلة:\n- 0.333... = 0.3̄\n- 0.1666... = 0.16̄\n- 0.272727... = 0.2̄7̄\n\nتحويل الكسر العشري الدوري إلى كسر اعتيادي (a / b):\nطريقة المعادلة الجبرية:\nمثال: حول 0.7̄ إلى كسر اعتيادي:\n1. نفرض أن: x = 0.7777...  (المعادلة 1)\n2. بما أن التكرار في مرتبة واحدة، نضرب الطرفين في 10:\n   10x = 7.7777...  (المعادلة 2)\n3. نطرح المعادلة 1 من المعادلة 2:\n   10x - x = 7.7777... - 0.7777...\n   9x = 7\n   x = 7 / 9.\nإذن 0.7̄ = 7 / 9 وهو عدد نسبي."
