            "text": "خطوات حل المسألة الأربع المعتمدة وزارياً:\n1. أفهم (Understand): تحديد المعطيات والمطلوب إيجاده بدقة.\n2. أخطط (Plan): وضع خطة الحل (التخمين والتحقق مع ضبط الاتجاه صعوداً أو هبوطاً).\n3. أحل (Solve): وضع جدول التخمينات وتعديلها حتى نصل للإجابة الصحيحة المطابقة لجميع الشروط.\n4. أتحقق (Check): التأكد من صحة الحل بالتعويض في شروط المسألة الأصلية.\n\nمسألة نموذجية:\nمستطيل محيطه 36 cm، وطوله يزيد على عرضه بمقدار 4 cm. فما أبعاده؟\nالحل:\n- المحيط = 2 × (الطول + العرض) = 36، إذن (الطول + العرض) = 18 cm.\n- نخمن العرض = 6 cm، فيكون الطول = 6 + 4 = 10 cm. المجموع = 10 + 6 = 16 cm (أقل من 18، نزيد التخمين).\n- نخمن العرض = 7 cm، فيكون الطول = 7 + 4 = 11 cm. المجموع = 11 + 7 = 18 cm (تخمين صحيح تماماً!).\n- إذن: العرض = 7 cm، والطول = 11 cm."
