            "text": "الفصل الثاني: الأعداد الحقيقية (Real Numbers)\n\nالأعداد غير النسبية (Irrational Numbers - H):\nهي الأعداد التي لا يمكن كتابتها بصورة كسر اعتيادي (a / b)، وتتميز بأنها كسور عشرية غير منتهية وغير دورية، وأهمها:\n1. الجذور التربيعية للأعداد التي ليست مربعات كاملة، مثل: √2 ≈ 1.414...، √3 ≈ 1.732...، √5 ≈ 2.236...\n2. الجذور التكعيبية للأعداد التي ليست مكعبات كاملة، مثل: ³√2، ³√4.\n3. النسبة الثابتة الباي (π ≈ 3.14159...).\n\nمجموعة الأعداد الحقيقية (Real Numbers - R):\nهي المجموعة الشاملة الناتجة من اتحاد مجموعة الأعداد النسبية (Q) مع مجموعة الأعداد غير النسبية (H):\n   R = Q ∪ H\nوتشمل بالتدرج: الأعداد الطبيعية N ⊂ الصحيحة Z ⊂ النسبية Q ⊂ الحقيقية R.\nملاحظة مهمة: الجذر التربيعي لعدد سالب (مثل √-9) لا ينتمي إلى R (عدد غير حقيقي)."
