            "text": "تقدير الجذور التربيعية للأعداد غير المربعة لأقرب عُشر:\nلحساب قيمة تقريبية لجذر عدد غير مربع، نحصره بين أقرب مربعين كاملين (أحدهما أصغر منه والآخر أكبر منه).\n\nمثال: قدر قيمة √7 ومثلها على خط الأعداد:\n1. نحصر العدد 7 بين المربعين الكاملين 4 و 9:\n   4 < 7 < 9\n2. بأخذ الجذر التربيعي للأطراف:\n   √4 < √7 < √9  =>  2 < √7 < 3\n3. بما أن 7 أقرب إلى 9 (الفرق 2) منه إلى 4 (الفرق 3)، فإن √7 أقرب إلى 3، وتكون قيمته التقديرية حوالي 2.6.\n4. التمثيل: نحدد النقطة بين 2 و 3 على مستقيم الأعداد أقرب إلى العدد 3."
