            "text": "1. إيجاد الجذرين التربيعيين الموجب والسالب للعدد الموجب:\nلكل عدد حقيقي موجب a جذران تربيعيان أحدهما موجب (+√a) والآخر سالب (-√a)، لأن (±√a)² = a.\nمثال: الجذران التربيعيان للعدد 36 هما: +6 و -6؛ وللعدد 9/25 هما: +3/5 و -3/5.\n\n2. نظرية فيثاغورس (Pythagorean Theorem):\nفي أي مثلث قائم الزاوية، مساحة المربع المنشأ على الوتر تساوي مجموع مساحتي المربعين المنشأين على الضلعين القائمين الآخرين:\n   c² = a² + b²\nحيث c هو طول الوتر (الضلع الأطول المقابل للزاوية القائمة)، و a, b هما طولا الضلعين القائمين.\n\n3. عكس نظرية فيثاغورس (Converse of Pythagorean Theorem):\nفي أي مثلث، إذا كان مربع طول أطول أضلاعه يساوي مجموع مربعي طولي الضلعين الآخرين، فإن المثلث يكون قائم الزاوية، والزاوية القائمة تقابل أطول الأضلاع:\n   إذا كان c² = a² + b² فإن المثلث قائم الزاوية.\n\nمثال تطبيقي:\nحدد إذا كان المثلث الذي أطوال أضلاعه 6 cm, 8 cm, 10 cm قائم الزاوية أم لا؟\nالحل النموذجي:\n1. أطول ضلع هو 10 cm، مربعه: 10² = 100.\n2. نربع الضلعين الآخرين ونجمعهما: 6² + 8² = 36 + 64 = 100.\n3. بما أن 10² = 6² + 8²، إذن حسب عكس نظرية فيثاغورس، المثلث قائم الزاوية.",
