            "text": "قاعدة الفرق بين مربعين:\nأي مقدار على صورة (حد مربع - حد مربع) يتحلل إلى حاصل ضرب فرقهما في مجموعهما:\n   a² - b² = (a - b)(a + b)\n\nأمثلة نموذجية:\n1. x² - 16 = (x - 4)(x + 4)\n2. 4y² - 49 = (2y - 7)(2y + 7)\n3. 3x² - 27: (نستخرج العامل المشترك 3 أولاً):\n   = 3(x² - 9) = 3(x - 3)(x + 3)\n4. (z + 1)² - 36 = [(z + 1) - 6][(z + 1) + 6] = (z - 5)(z + 7)."
