            "text": "1. حل المعادلات باستعمال خاصية الجذر التربيعي:\nإذا كان x² = a (حيث a ≥ 0):\nفإن: x = ±√a (لأن للعدد الموجب جذرين أحدهما موجب والآخر سالب).\n- إذا كان a < 0 فمجموعة الحل في R خالية (S = ∅).\nمثال 1: x² = 25 => x = ±√25 = ±5 (S = {5, -5}).\nمثال 2: 3y² = 36 => y² = 12 => y = ±√12 = ±2√3.\n\n2. حل المعادلات باستعمال خاصية الضرب الصفري:\nإذا كان حاصل ضرب مقدارين يساوي صفراً: A × B = 0، فإن: إما A = 0 أو B = 0.\nمثال 3: حل المعادلة (x - 4)(x + 7) = 0\n- إما x - 4 = 0 => x = 4\n- أو x + 7 = 0 => x = -7 => S = {4, -7}.\nوكذلك بالتحليل بالعامل المشترك أو الفرق بين مربعين قبل تطبيق الضرب الصفري.\n\n3. حل المعادلات التي تحتوي على جذر تربيعي:\nنعزل الجذر في طرف ثم نربع الطرفين: إذا كان √x = a (a ≥ 0) فإن x = a².\nمثال 4: √(x + 3) = 4 => x + 3 = 16 => x = 13 (S = {13})."
