            "text": "المتباينة (Inequality):\nجملة رياضية مفتوحة تحوي إحدى علاقات الترتيب: أكبر من (>)، أصغر من (<)، أكبر من أو يساوي (≥)، أو أصغر من أو يساوي (≤).\n\nخصائص المتباينات الجوهرية:\n1. الجمع والطرح: لا يغيران اتجاه رمز التباين عند إضافة أو طرح نفس العدد من الطرفين.\n2. الضرب والقسمة في عدد موجب: لا يغيران اتجاه رمز التباين.\n3. قاعدة القلب الهامة: عند ضرب أو قسمة طرفي المتباينة على عدد سالب، يجب عكس اتجاه رمز التباين فوراً:\n   - يتحول (>) إلى (<)، و (≥) إلى (≤)، والعكس بالعكس.\n\nمثال 1:\nحل المتباينة ومثلها على مستقيم الأعداد: 3x - 4 < 2\nالحل:\n1. نضيف 4 للطرفين: 3x < 2 + 4 => 3x < 6\n2. نقسم على 3 (موجب، لا تنقلب الإشارة): x < 2.\n3. مجموعة الحل: S = { x ∈ R : x < 2 }.\n4. التمثيل: دائرة مفتوحة عند العدد 2، والتظليل يمتد لليسار."
