            "text": "الفصل الخامس: الهندسة والقياس (Geometry and Measurement)\n\nإذا قطع مستقيم مستقيمين في مستوٍ واحد، تتكون ثماني زوايا لها علاقات خاصة:\n1. الزاويتان المتناظرتان (Corresponding Angles): زاويتان إحداهما داخلية والأخرى خارجية، تقعان على جهة واحدة من القاطع وغير متجاورتين.\n2. الزاويتان المتبادلتان (Alternate Angles): زاويتان داخليتان تقعان في جهتين مختلفتين من القاطع وغير متجاورتين.\n3. الزاويتان الداخليتان (Interior Angles): زاويتان داخليتان تقعان على جهة واحدة من القاطع.\n\nعكس مبرهنات التوازي لإثبات توازي مستقيمين (L₁ // L₂):\n1. عكس مبرهنة الزوايا المتناظرة: إذا قطع مستقيم مستقيمين وكانت الزاويتان المتناظرتان متساويتين في القياس، فإن المستقيمين متوازيان.\n2. عكس مبرهنة الزوايا المتبادلة: إذا قطع مستقيم مستقيمين وكانت الزاويتان المتبادلتان متساويتين في القياس، فإن المستقيمين متوازيان.\n3. عكس مبرهنة الزوايا الداخلية: إذا قطع مستقيم مستقيمين وكان مجموع قياس الزاويتين الداخليتين يساوي 180° (متكاملتان)، فإن المستقيمين متوازيان."
