            "text": "تطابق المثلثين (Congruence of Triangles - الرمز ≅):\nيتطابق مثلثان إذا تطابقت أضلاعهما وزواياهما المتناظرة، ويكفي تحقق إحدى الحالات الثلاث الآتية:\n\n1. الحالة الأولى (ض.ض.ض - SSS): يتطابق مثلثان إذا تطابقت أضلاع المثلث الأول الثلاثة مع الأضلاع المناظرة لها في المثلث الثاني.\n2. الحالة الثانية (ض.ز.ض - SAS): يتطابق مثلثان إذا تطابق ضلعان والزاوية المحددة (المحصورة) بينهما في المثلث الأول مع نظائرها في المثلث الثاني.\n3. الحالة الثالثة (ز.ض.ز - ASA): يتطابق مثلثان إذا تطابقت زاويتان والضلع المحدد (الواصل) بين رأسيهما في المثلث الأول مع نظائرها في المثلث الثاني.\n\nنتائج التطابق:\nإذا تطابق مثلثان (ΔABC ≅ ΔDEF)، تتطابق كافة العناصر المتناظرة الأخرى من أضلاع وزوايا."
