            "text": "1. خواص المثلث المتساوي الساقين (Isosceles Triangle):\n- فيه ضلعان متساويان في الطول يسميان الساقين، والضلع الثالث يسمى القاعدة.\n- تتساوى قياس زاويتي القاعدة المقابلتين للضلعين المتساويين (وعكسها صحيح: إذا تساوت زاويتان في مثلث تساوى الضلعان المقابلان لهما).\n- منصف زاوية الرأس يكون عمودياً على القاعدة وينصفها.\n\n2. خواص المثلث المتساوي الأضلاع (Equilateral Triangle):\n- جميع أضلاعه الثلاثة متساوية في الطول.\n- جميع زواياه متساوية في القياس، وقياس كل منها 60° دائماً (180° ÷ 3 = 60°).\n\n3. خواص المثلث القائم الزاوية (Right-Angled Triangle):\n- فيه زاوية قائمة قياسها 90°، والزاويتان الحادتان متتامتان (مجموعهما 90°).\n- الضلع المقابل للزاوية القائمة يسمى الوتر وهو أطول أضلاعه، وتنطبق عليه نظرية فيثاغورس: c² = a² + b²."
