            "heading": "خواص متوازي الأضلاع والمعين وشبه المنحرف (صفحة 18 - 19)",
            "text": "1. متوازي الأضلاع (Parallelogram):\n- كل ضلعين متقابلين متوازيان ومتطابقان في الطول.\n- كل زاويتين متقابلتين متساويتان في القياس، وكل زاويتين متتاليتين متكاملتان (مجموعهما 180°).\n- القطران ينصف كل منهما الآخر.\n- المساحة = طول القاعدة × الارتفاع، والمحيط = 2 × (مجموع ضلعين متجاورين).\n\n2. المعين (Rhombus):\n- هو متوازي أضلاع جميع أضلاعه الأربعة متساوية في الطول.\n- قطراه متعامدان وينصف كل منهما الزاويتين عند طرفيه.\n- المساحة = طول الضلع × الارتفاع، أو: المساحة = ½ × حاصل ضرب طولي قطريه (½ · d₁ · d₂).\n- المحيط = 4 × طول الضلع.\n\n3. شبه المنحرف (Trapezoid):\n- شكل رباعي فيه ضلعان فقط متوازيان يسميان قاعدتي شبه المنحرف (a و b).\n- المساحة = ½ × (a + b) × h  (نصف مجموع القاعدتين المتوازيتين × الارتفاع).\n- المحيط = مجموع أطوال أضلاعه الأربعة."
