            "text": "1. الهرم المنتظم (Regular Pyramid):\n- المساحة الجانبية (L.A) = ½ × محيط القاعدة (P) × الارتفاع الجانبي (l).\n- المساحة الكلية (T.A) = L.A + مساحة القاعدة (B).\n- الحجم (V) = ⅓ × مساحة القاعدة (B) × الارتفاع العمودي (h).\n\n2. المخروط الدائري القائم (Right Circular Cone):\n- يربط الارتفاع الجانبي (l) والارتفاع العمودي (h) ونصف القطر (r) علاقة فيثاغورس: l² = h² + r².\n- المساحة الجانبية: L.A = π · r · l\n- المساحة الكلية: T.A = π · r · l + π · r²\n- الحجم: V = ⅓ · π · r² · h"
