            "text": "الشكل المركب (Composite Shape) هو شكل مستوٍ يتكون من شكلين بسيطين أو أكثر (مثل مربع، مستطيل، مثلث، شبه منحرف، دائرة أو نصف دائرة).\n\nخطوات إيجاد مساحة الشكل المركب:\n1. تقسيم الشكل المركب بخطوط مساعدة إلى أشكال هندسية بسيطة معلومة القوانين.\n2. استنتاج أي بُعد مفقود باستخدام خصائص الأضلاع المتقابلة أو نصف القطر.\n3. حساب مساحة كل جزء بسيط على حدة.\n4. جمع مساحات الأجزاء لتكوين المساحة الكلية (أو طرح مساحة الجزء المفرغ إذا كان الشكل يحتوي على فتحة أو اقتطاع)."
