            "text": "1. مقدمة في الدوال (Introduction to Functions):\n- العلاقة (Relation): ربط بين عناصر مجموعة المدخلات (المجال X) وعناصر مجموعة المخرجات (المجال المقابل Y).\n- الدالة (Function): علاقة تحدد لكل قيمة مدخلة (x) قيمة مخرجة واحدة فقط (y).\n- شروط تمييز الدالة:\n  * في المخطط السهمي: يخرج من كل عنصر في المجال سهم واحد فقط.\n  * في الأزواج المرتبة: لا يتكرر الإحداثي الأول (x) مرتين مع مخرجات مختلفة.\n  * في الرسم البياني (اختبار الخط العمودي): إذا قطع أي خط عمودي الرسم في نقطة واحدة فقط فالعلاقة دالة.\n\n2. ميل المستقيم (Slope - m):\nهو النسبة بين التغير العمودي (Δy) والتغير الأفقي (Δx) بين نقطتين (x₁, y₁) و (x₂, y₂):\n   m = (y₂ - y₁) / (x₂ - x₁)   (حيث x₂ ≠ x₁)\n- حالات الميل الأربع: موجب (m > 0 صاعد)، سالب (m < 0 هابط)، صفر (m = 0 أفقي // محور X)، غير معرّف (Δx = 0 شاقولي // محور Y).\n- توازي المستقيمين: L₁ // L₂ ⇔ m₁ = m₂.\n- تعامد المستقيمين: L₁ ⊥ L₂ ⇔ m₁ × m₂ = -1."
