            "text": "الدالة الخطية (Linear Function):\nهي دالة تمثيلها البياني على المستوي الإحداثي يمثل خطاً مستقيماً غير عمودي، وتُكتب بصيغتها القياسية:\n   y = m x + k\nحيث m هو ميل المستقيم (معدل التغير الثابت) و k هو المقطع الصادي (تقاطع المستقيم مع محور Y عند (0, k)).\n\nصيغ كتابة معادلة المستقيم:\n1. صيغة الميل والمقطع: y = m x + k\n2. صيغة الميل ونقطة (x₁, y₁): y - y₁ = m (x - x₁)\n3. صيغة النقطتين (x₁, y₁) و (x₂, y₂): نحسب الميل m = (y₂ - y₁)/(x₂ - x₁) ثم نعوض في صيغة الميل ونقطة."
