            "text": "1. بيان الشاربين (Box-and-Whisker Plot):\nتمثيل بياني يظهر تشتت البيانات وتوزعها حول الوسيط باستعمال القيم الخمس الآتية بعد الترتيب التصاعدي:\n- القيمة الصغرى (Minimum) والقيمة العظمى (Maximum).\n- الوسيط (Q₂): يقسم البيانات إلى نصفين (نصف أدنى ونصف أعلى).\n- الربيع الأدنى (Q₁): وسيط النصف الأدنى من البيانات.\n- الربيع الأعلى (Q₃): وسيط النصف الأعلى من البيانات.\n- المدى الربيعي (IQR) = Q₃ - Q₁ (يمثل طول الصندوق ويضم 50% من البيانات الوسطى).\n\n2. القطاعات الدائرية (Pie Charts):\nزاوية كل قطاع = (تكرار الفئة / العدد الكلي) × 360°  أو  (النسبة المئوية × 360°)، ومجموع الزوايا = 360°."
