            "text": "1. التجربة العشوائية (Random Experiment): هي نشاط نعلم مسبقاً جميع نواتجه الممكنة، ولكن لا يمكن الجزم أيها سيحدث قبل إجراء التجربة (مثل رمي قطعة نقود أو حجر نرد).\n2. فضاء العينة (Sample Space - S): مجموعة كل النواتج الممكنة للتجربة العشوائية، ويُمثل بطريقتين:\n   - الرسم الشجري (Tree Diagram).\n   - الجدول أو القوائم المنظمة.\n3. مبدأ العد الأساسي (Fundamental Counting Principle):\nإذا أمكن إجراء التجربة الأولى بعدد طرق (m) والثانية بعدد طرق (n)، فإن عدد النواتج الكلي لإجرائهما معاً = m × n."
