            "text": "احتمال وقوع الحدث E:\nهو قياس عددياً لفرصة تحقق الحدث، ويُحسب بالقانون:\n   P(E) = m / n\nحيث m هو عدد نواتج الحدث E، و n هو العدد الكلي لنواتج فضاء العينة S.\n\nخصائص الاحتمال الأساسية:\n1. قيمة أي احتمال تقع دائماً بين 0 و 1:  0 ≤ P(E) ≤ 1  (أو بين 0% و 100%).\n2. احتمال الحدث المستحيل = 0 (0%)، واحتمال الحدث المؤكد = 1 (100%).\n3. احتمال الحدث المتمم (عدم وقوع الحدث E): P(E') = 1 - P(E)."
