        "title": "الأعداد الحقيقية ونظرية فيثاغورس (20 درجة)",
        "marks": "20 درجة",
        "content": "<p><strong>أجب عن فرعين فقط (لكل فرع 10 درجات):</strong></p><p><strong>أ)</strong> بسط الجملة العددية بتنسيب المقام: <code>(√5 - 2) / √5</code></p><p><strong>ب)</strong> بين هل المثلث الذي أطوال أضلاعه <code>9 cm, 12 cm, 15 cm</code> قائم الزاوية أم لا؟ مع ذكر السبب.</p><p><strong>ج)</strong> جد المسافة بين النقطتين <code>A(1, 3)</code> و <code>B(5, 6)</code> في المستوي الإحداثي.</p>",
        "solution": "<div style='line-height: 1.8;'><strong>الحل النموذجي لس2:</strong><br><strong>فرع (أ):</strong><br>نضرب البسط والمقام في √5:<br>= [(√5 - 2)/√5] × (√5/√5) = (√5×√5 - 2√5) / 5 = <strong>(5 - 2√5) / 5</strong>.<br><br><strong>فرع (ب):</strong><br>1. أطول الأضلاع 15 cm، مربعه: 15² = 225.<br>2. مجموع مربعي الضلعين الآخرين: 9² + 12² = 81 + 144 = 225.<br>3. بما أن 15² = 9² + 12² (225 = 225)، إذن حسب <strong>عكس نظرية فيثاغورس، المثلث قائم الزاوية</strong>.<br><br><strong>فرع (ج):</strong><br>قانون المسافة: d = √[(5 - 1)² + (6 - 3)²] = √[4² + 3²] = √[16 + 9] = √25 = <strong>5 وحدات طول</strong>.</div>"
