        "title": "المقادير الجبرية والتحليل (20 درجة)",
        "marks": "20 درجة",
        "content": "<p><strong>أجب عن فرعين فقط (لكل فرع 10 درجات):</strong></p><p><strong>أ)</strong> جد ناتج ضرب المقدارين الجبريين: <code>(2x - 3)(3x + 4)</code></p><p><strong>ب)</strong> حلل المقدار الآتي باستخراج العامل المشترك الأكبر (G.C.F): <code>12x³y² - 18x²y³ + 6x²y</code></p><p><strong>ج)</strong> حلل المقدارين الآتيين: <code>(1) 25x² - 49</code> ، <code>(2) 2y² - 50</code></p>",
        "solution": "<div style='line-height: 1.8;'><strong>الحل النموذجي لس3:</strong><br><strong>فرع (أ):</strong><br>التوزيع المزدوج: 2x(3x) + 2x(4) - 3(3x) - 3(4) = 6x² + 8x - 9x - 12 = <strong>6x² - x - 12</strong>.<br><br><strong>فرع (ب):</strong><br>G.C.F للأعداد 12, 18, 6 هو 6، وللمتغيرات بأصغر أس هو x²y.<br>إذن: G.C.F = 6x²y.<br>التحليل: = <strong>6x²y (2xy - 3y² + 1)</strong>.<br><br><strong>فرع (ج):</strong><br>1. 25x² - 49 = (5x)² - (7)² = <strong>(5x - 7)(5x + 7)</strong>.<br>2. 2y² - 50 = 2(y² - 25) = <strong>2(y - 5)(y + 5)</strong>.</div>"
