        "marks": "20 درجة",
        "content": "<p><strong>أجب عن فرعين فقط (لكل فرع 10 درجات):</strong></p><p><strong>أ)</strong> حل المعادلة الآتية في R: <code>3(x + 4) = x + 20</code></p><p><strong>ب)</strong> جد مجموعة حل معادلة القيمة المطلقة: <code>|2x - 5| = 9</code></p><p><strong>ج)</strong> حل المتباينة الآتية في R ومثل الحل على مستقيم الأعداد: <code>-3x + 4 ≤ 19</code></p>",
        "solution": "<div style='line-height: 1.8;'><strong>الحل النموذجي لس4:</strong><br><strong>فرع (أ):</strong><br>1. نفك الأقواس: 3x + 12 = x + 20.<br>2. ننقل المتغيرات والأعداد: 3x - x = 20 - 12 => 2x = 8 => x = 8 / 2 = <strong>4</strong>.<br>مجموعة الحل: <strong>S = {4}</strong>.<br><br><strong>فرع (ب):</strong><br>بما أن 9 > 0، نأخذ الحالتين:<br>- إما: 2x - 5 = 9 => 2x = 14 => x = 7.<br>- أو: 2x - 5 = -9 => 2x = -4 => x = -2.<br>مجموعة الحل: <strong>S = {7, -2}</strong>.<br><br><strong>فرع (ج):</strong><br>1. نطرح 4 من الطرفين: -3x ≤ 19 - 4 => -3x ≤ 15.<br>2. نقسم على -3 ونعكس رمز التباين: x ≥ 15 / (-3) => <strong>x ≥ -5</strong>.<br>مجموعة الحل: <strong>S = { x ∈ R : x ≥ -5 }</strong>، التمثيل: دائرة مغلقة عند -5 والتظليل يمتد لليمين.</div>"
